import pytest
from fastapi import APIRouter, FastAPI, Request
from fastapi.routing import APIRoute
from fastapi.testclient import TestClient


@pytest.mark.parametrize(\"redirect_slashes\", [True, False])
def test_strict_slashes(redirect_slashes):
    app = FastAPI(redirect_slashes=redirect_slashes)
    router = APIRouter(strict_slashes=False)
    strict_router = APIRouter()

    @router.get(\"/users\")
    def users(request: Request):
        return {\"path\": request.url.path}

    @strict_router.get(\"/users2\")
    def users2():
        return {\"users\": []}

    app.include_router(router)
    app.include_router(strict_router)
    client = TestClient(app, follow_redirects=False)

    for path in (\"/users\", \"/users/\"):
        response = client.get(path)
        assert response.status_code == 200
        assert response.json() == {\"path\": path}
        assert \"location\" not in response.headers

    assert client.get(\"/users2\").status_code == 200
    assert client.get(\"/users2/\").status_code == (307 if redirect_slashes else 404)
    assert set(app.openapi()[\"paths\"]) == {\"/users\", \"/users2\"}
    assert str(app.url_path_for(\"users\")) == \"/users\"


@pytest.mark.parametrize(\"path\", [\"/users/{user_id}\", \"/users/{user_id}/\"])
@pytest.mark.parametrize(\"included\", [True, False])
def test_parameterized_routes(path, included):
    router = APIRouter(strict_slashes=False)

    @router.get(path)
    def user(user_id: int):
        return {\"user_id\": user_id}

    if included:
        parent = APIRouter()
        parent.include_router(router, prefix=\"/v1\")
        app = FastAPI(redirect_slashes=False)
        app.include_router(parent, prefix=\"/api\")
        client = TestClient(app, follow_redirects=False)
        prefix = \"/api/v1\"
    else:
        client = TestClient(router, follow_redirects=False)
        prefix = \"\"

    for suffix in (\"\", \"/\"):
        response = client.get(f\"{prefix}/users/42{suffix}\")
        assert response.status_code == 200
        assert response.json() == {\"user_id\": 42}
        assert client.post(f\"{prefix}/users/42{suffix}\").status_code == 405


@pytest.mark.parametrize(\"strict_slashes\", [True, False])
def test_add_api_route_default_and_override(strict_slashes):
    router = APIRouter(strict_slashes=strict_slashes)
    router.add_api_route(\"/default\", lambda: {})
    router.add_api_route(\"/override\", lambda: {}, strict_slashes=not strict_slashes)
    assert isinstance(router.routes[0], APIRoute)
    assert router.routes[0].strict_slashes is strict_slashes
    app = FastAPI(redirect_slashes=False)
    app.include_router(router)
    client = TestClient(app, follow_redirects=False)
    assert client.get(\"/default/\").status_code == (404 if strict_slashes else 200)
    assert client.get(\"/override/\").status_code == (200 if strict_slashes else 404)


def test_root_route_and_routes_added_after_include():
    app = FastAPI(redirect_slashes=False)
    router = APIRouter(strict_slashes=False)
    app.include_router(router, prefix=\"/api\")
    router.add_api_route(\"/\", lambda: {})
    client = TestClient(app, follow_redirects=False)
    assert client.get(\"/api\").status_code == 200
    assert client.get(\"/api/\").status_code == 200
